const m = $input.item.json;
const bins = $input.item.binary || {};
const h = m.headers || {};
const rfcId = m.messageId || h['message-id'] || null;
const d = new Date(m.internalDate ? Number(m.internalDate) : (m.date || h.date));
const folder = `${m.threadId}_${m.id}`;
return {
  json: {
    gmail_id: m.id,
    thread_id: m.threadId,
    rfc_message_id: rfcId,
    label_ids: '{' + (m.labelIds || []).join(',') + '}',
    received_at: isNaN(d) ? null : d.toISOString(),
    message: JSON.stringify(m),
    folder_name: folder,
    folder_path: `bronze/gmail/${folder}/`,
    attachment_count: Object.keys(bins).length,
    n8n_execution_id: String($execution.id)
  },
  binary: bins
};

const fs = require('fs');
const ROOT = '/home/node/.n8n-files/bronze/gmail';
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const dir = `${ROOT}/${item.json.threadId}_${item.json.id}`;
  const keys = Object.keys(item.binary ?? {});
  if (keys.length) fs.mkdirSync(dir, { recursive: true });

  for (let k = 0; k < keys.length; k++) {
    const buf = await this.helpers.getBinaryDataBuffer(i, keys[k]);
    const safe = item.binary[keys[k]].fileName.replace(/[\\/:*?"<>|]/g, '_');
    const path = `${dir}/${k}_${safe}`;
    fs.writeFileSync(path, buf);
    out.push({ json: { gmail_id: item.json.id, file: path, bytes: buf.length } });
  }
}
return out;
